/**
 * Are the conventions in `src/stories/` actually followed?
 *
 * They are real, consistent, and enforced entirely by hand. This repo has a
 * dozen gates of exactly this kind — structural rules over authored files, no
 * browser needed — and `src/stories/` was covered by one of them, on colour
 * literals only.
 *
 * The cost of not having it is already written down as a *warning* rather than a
 * check. From `tests/visual.spec.ts`:
 *
 *   > The first five names are unchanged from when this file listed them by hand
 *   > — their baselines are still valid and **must not be regenerated by a
 *   > rename**.
 *
 * A story retitled from `Foundations/Button` to `Components/Button` changes its
 * id, orphans a committed PNG, and produces a new baseline nobody reviewed. That
 * comment is the mitigation; this is the check.
 *
 * Reads `storybook-static/index.json` — the same file `check:visual-coverage`
 * and `check:docgen-props` read, so all three agree about what a story is.
 *
 *   node scripts/check-story-conventions.mjs           verify
 *   node scripts/check-story-conventions.mjs --list    print the census
 */

import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

/**
 * The sidebar vocabulary, closed on purpose.
 *
 * Order is the reading order `preview.ts` sorts by, and it is an argument: token
 * surfaces first, product mockups last. A new group here is a decision about
 * what this system claims to be, not a filing choice.
 */
const GROUPS = ['Guides', 'Foundations', 'Docs', 'Blog', 'Presentation', 'SaaS', 'Showcase'];

/**
 * Titles that are a single page rather than a group, so `<Group>/<Name>` does
 * not apply. One entry, and it should stay that way: a second top-level page is
 * a sidebar with two front doors.
 */
const SINGLE_PAGES = { Manifesto: 'The landing page. A group of one is not a group.' };

/**
 * Titles that deliberately have no docs page, and why.
 *
 * A bare absence is what `check:visual-coverage`'s excluded-with-a-reason
 * pattern exists to prevent, and the argument applies verbatim: seven of these
 * are compositions where a props table would be noise, and saying so is cheap.
 */
const NO_DOCS_PAGE = {
  'Blog/LoremIpsumPost': 'A fixture post. Its API is the prose it renders.',
  'Docs/Portal': 'A composition of the whole docs chrome; the parts carry the docs.',
  'Foundations/Theme Ladder': 'Renders every Level side by side — a specimen, not an API.',
  'Presentation/SlideDeck': 'A composition. `Slide` carries the props table.',
  'SaaS/AdminDashboardLayout': 'A product mockup, not a published component API.',
  'SaaS/LandingPage': 'A product mockup, not a published component API.',
  'Showcase/DesignSandbox': 'An interactive sandbox; it takes no props.',
};

/**
 * The status vocabulary, closed — Storybook's own feature-lifecycle words.
 *
 * The maturity differences inside this package are known, measured and written
 * down in `docs/surface-readiness.md`: `Docs/*` at ~90% with "nothing
 * structural" blocking it, the SaaS mockups at ~20-25% and described there as
 * "screenshots of one specific product". A consumer browsing the sidebar saw one
 * flat list in which `Docs/Prose` and `SaaS/LandingPage` looked equally
 * load-bearing.
 *
 * The gap was never that the maturity was unknown. It was that it was known and
 * not surfaced where the choice gets made.
 */
const STATUSES = ['stable', 'experimental', 'preview', 'deprecated'];

const index = JSON.parse(readFileSync(path.join(ROOT, 'storybook-static/index.json'), 'utf8'));
const entries = Object.values(index.entries ?? {});
const titles = [...new Set(entries.map((e) => e.title))].sort();
const withDocs = new Set(entries.filter((e) => e.type === 'docs').map((e) => e.title));

const problems = [];

for (const title of titles) {
  if (SINGLE_PAGES[title]) continue;

  const [group, ...rest] = title.split('/');

  if (!GROUPS.includes(group)) {
    problems.push(
      `${title} — "${group}" is not a group. The vocabulary is: ${GROUPS.join(', ')}.`,
    );
  }
  if (rest.length === 0) {
    problems.push(`${title} — a title must be <Group>/<Name>; this has no name.`);
  }
  if (rest.length > 1) {
    problems.push(`${title} — a title must be <Group>/<Name>; this nests ${rest.length} deep.`);
  }
  const tags = new Set(entries.filter((e) => e.title === title).flatMap((e) => e.tags ?? []));
  const statuses = STATUSES.filter((status) => tags.has(status));
  if (statuses.length === 0) {
    problems.push(
      `${title} — no status tag. Add exactly one of: ${STATUSES.join(', ')}, matching docs/surface-readiness.md.`,
    );
  } else if (statuses.length > 1) {
    problems.push(`${title} — ${statuses.length} status tags (${statuses.join(', ')}); exactly one.`);
  }

  if (!withDocs.has(title) && !NO_DOCS_PAGE[title]) {
    problems.push(
      `${title} — no docs page and no stated reason. Add \`tags: ['autodocs']\`, or a reason in NO_DOCS_PAGE.`,
    );
  }
  if (withDocs.has(title) && NO_DOCS_PAGE[title]) {
    problems.push(`${title} — listed in NO_DOCS_PAGE but has a docs page. Remove the entry.`);
  }
}

if (process.argv.includes('--list')) {
  for (const group of GROUPS) {
    const own = titles.filter((t) => t.startsWith(`${group}/`));
    console.log(`${group} (${own.length})`);
    for (const t of own) {
      console.log(`  ${withDocs.has(t) ? 'docs' : '    '}  ${t}`);
    }
  }
  console.log('');
}

console.log(
  `Story conventions OK — ${titles.length} titles across ${GROUPS.length} groups, ${Object.keys(NO_DOCS_PAGE).length} without a docs page by decision.`,
);

if (problems.length) {
  console.error(`\nStory conventions check failed — ${problems.length} problem(s):\n`);
  for (const p of problems) console.error(`  - ${p}`);
  console.error(
    '\nA retitled story changes its id, which orphans its committed baseline —\n' +
      'see the warning at the top of tests/visual.spec.ts.',
  );
  process.exit(1);
}
